typedef float rational_t;
typedef float time_value_t;
typedef float fp;

float pow(float, float);
void fast_sin_cos_approx(fp rads, fp *sinx, fp *cosx);

inline fp fast_sin(fp rads)
{
  fp sinx, cosx;
  fast_sin_cos_approx(rads, &sinx, &cosx);
  return sinx;
}

inline fp fast_cos(fp rads)
{
  fp sinx, cosx;
  fast_sin_cos_approx(rads, &sinx, &cosx);
  return cosx;
}

class float_filter
{
public:
  void Filter_Float(float &filtered_float, time_value_t time_step,
                    float filter_speed_r, float filter_speed_i);

private:
  rational_t Pos[2];
  rational_t err[2];
};

void float_filter::Filter_Float(float &filtered_float, time_value_t time_step,
                                float filter_speed_r, float filter_speed_i)
{
	if (time_step > 0.1f)
		time_step = 0.1f;
	else if (time_step < 0.014f)
		time_step = 0.014f;

	if (filter_speed_i == 1000000)
		filter_speed_i = filter_speed_r;

	float r = filter_speed_r*6.9282f;
	float i = filter_speed_i*4.0f;

	float eneg = 0.36787944f;
	float coeff = pow(eneg,r*time_step);
	float coss = fast_cos(i*time_step);
	float sins = fast_sin(i*time_step);
	float r1 = -coeff*coss;
	float i1 = coeff*sins;

	float a = r1*r1 + i1*i1;
	float g = 2.0f*r1 + a + 1.0f;

	float error = filtered_float - Pos[0];
    filtered_float = (a+1.0f)*Pos[0] - a*Pos[1] + g*err[0];

    Pos[1] = Pos[0];
    Pos[0] = filtered_float;
    err[1] = err[0];
    err[0] = error;
}
